(function(raiz){var HORAS_MES_JORNADA=160;var SEMANAS_MES=52/12;var TAREAS=[["leads","Pasar leads al CRM y dar la primera respuesta","Los leads de Meta entran solos al CRM y el setter IA contesta en WhatsApp","solo",10],["contratos","Preparar contratos y perseguir firmas","El contrato sale de la operación, en tres idiomas, y la firma se recuerda y caduca sola","prepara",8],["facturas","Emitir facturas y recibís","Cada factura sale del contrato y del hito que toca","prepara",6],["cobros","Llevar el calendario de cobros","Lo cobrado y lo pendiente se calculan con los recibís, no a mano","solo",6],["comisiones","Calcular comisiones","La comisión se genera desde la venta","solo",4]];var DEFECTO={coste:2500,pct:50};function num(v,min,max){var n=typeof v==="number"?v:parseFloat(String(v).replace(",","."));if(!isFinite(n))n=0;return Math.min(max,Math.max(min,n))}function calcula(horas,coste,pct){var semana=0;TAREAS.forEach((function(t){semana+=num(horas&&horas[t[0]],0,168)}));var c=num(coste,0,1e12),p=num(pct,0,100)/100;var horasMes=semana*SEMANAS_MES*p;var puestos=horasMes/HORAS_MES_JORNADA;return{horasSemanaEquipo:semana,horasMes:horasMes,puestos:puestos,valorMes:puestos*c,valorAno:puestos*c*12}}function frasePuestos(p){if(p<.1)return"unas horas sueltas al mes";if(p<.4)return"una media jornada larga a la semana";if(p<.65)return"media persona a jornada completa";if(p<.9)return"casi una persona a jornada completa";if(p<1.15)return"una persona a jornada completa";return"unas "+(Math.round(p*2)/2).toLocaleString("es-ES")+" personas a jornada completa"}var api={TAREAS:TAREAS,DEFECTO:DEFECTO,HORAS_MES_JORNADA:HORAS_MES_JORNADA,SEMANAS_MES:SEMANAS_MES,calcula:calcula,frasePuestos:frasePuestos};if(typeof module!=="undefined"&&module.exports)module.exports=api;else raiz.AXW_ROI=api})(this);